class Orders(Sequence[Order]):
    def __init__(self, items: Iterable[Order] = ()) -> None:
        self._items = tuple(items)            # snapshot, never a live list
    def __len__(self) -> int: return len(self._items)
    def __getitem__(self, index: int) -> Order: return self._items[index]
    def add(self, order: Order) -> "Orders":
        if len(self._items) >= MAX_ORDERS:
            raise OrderLimitExceeded
        return Orders((*self._items, order))  # new immutable collection
# the Sequence mixins provide __iter__, __contains__, index and count
